import { IngestPipeline, Key } from "@514labs/moose-lib";

// User Activity Events Data Model
// Optimized for:
// 1. Activity counts per user over date ranges
// 2. Total duration per action type
export interface UserActivity {
  event_id: Key<string>;
  event_ts: Date;
  user_id: string;
  action: string;
  duration_ms: number;
}

// Create ingestion pipeline with optimized table ordering
// Order by user_id first for user-based queries, then event_ts for time ranges
// This enables efficient queries for activity counts per user over date ranges
export const UserActivityPipeline = new IngestPipeline<UserActivity>("user_activity", {
  ingestApi: true, // Creates REST API at POST localhost:4000/ingest/user_activity
  stream: true,    // Creates Kafka/Redpanda topic for streaming
  table: {
    orderByFields: ["user_id", "event_ts", "action"] // Optimized for user + time + action queries
  }
});

